from pathlib import Path
import base64, hashlib, subprocess, zlib

path=Path("lib/main.dart")
expected_pre="4841cc7109ba2bf395735a9281925718f12928efdc8981dad9442aa1037a60e4"
expected_post="ec286209f3fec354210d867d5b4d148923cd995db4e3ba080c7bb5e01888de47"
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_pre:
    raise SystemExit(f"v321 baseline mismatch: expected {expected_pre}, got {actual}")
blob=''
patch=zlib.decompress(base64.b64decode(blob))
subprocess.run(["patch","--batch","--forward","--reject-file=-","-p0"],input=patch,check=True)
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_post:
    raise SystemExit(f"v321 output mismatch: expected {expected_post}, got {actual}")
body=path.read_text(encoding="utf-8")
for needle in [
    "bridgepoint-v321-resilience-expansion-eta-radar-map",
    "bridgepoint-v320-resilience-market-guard-service-credit",
    "bridgepoint_public_system_status_v320",
    "bridgepoint_user_market_context_v320",
    "bridgepoint_owner_resilience_metrics_v320",
    "bridgepoint_public_expansion_status_v321",
    "Calculating from live throughput",
    "Queued • position",
    "U.S. precipitation radar on • expansion badges hidden so the radar stays clear.",
    "LIVE SOURCE OUTAGES",
    "AUTO-DISCOVERY PENDING",
]:
    if needle not in body:
        raise SystemExit(f"v321 release marker missing: {needle}")
print("BridgePoint v321 resilience + expansion ETA + radar/map patch applied and verified.")
